  f2.setValue('Market Cap')
    .setFontWeight('bold')
    .setFontSize(11)
    .setBackground('#FEFCBF')
    .setHorizontalAlignment('center')
    .setVerticalAlignment('middle');

  // Control 4: Horizon (Cols G-H)
  sheet.getRange('G2').setValue('Horizon:')
